    {"idezet": "Eszmélet: / Földtől eloldoz az ég, / És a hajnal a fák közt / Lassan szétterül.", "szerzo": "József Attila", "mu": "Eszmélet"},
    {"idezet": "Levegőt!: / Ki tiltja meg, hogy elmondjam, mi bántott / Hazafelé menet?", "szerzo": "József Attila", "mu": "Levegőt!"},
    {"idezet": "Születésnapomra: / Harminckét éves lettem én – / Meglepetés e költemény", "szerzo": "József Attila", "mu": "Születésnapomra"},
    {"idezet": "Talán eltűnök hirtelen, / Akár az erdőben a vadnyom.", "szerzo": "József Attila", "mu": "Talán eltűnök hirtelen"},
