    {"idezet": "Erőltetett menet: / Bolond, ki földre rogyván fölkél és újra lépked, / S vándorló fájdalomként mozdít bokát és térdet,", "szerzo": "Radnóti Miklós", "mu": "Erőltetett menet"},
    {"idezet": "Hetedik ecloga: / Látod-e, esteledik s a szögesdróttal beszegett, vad / Tölgykerítés, barakk lebeg, elnyeli őket az este.", "szerzo": "Radnóti Miklós", "mu": "Hetedik ecloga"},
    {"idezet": "Razglednicák: / Mellézuhantam, átfordult a teste / S feszes volt már, mint húr, ha pattan.", "szerzo": "Radnóti Miklós", "mu": "Razglednicák (4.)"},
    {"idezet": "Tétova óda: / Mióta készülök, hogy elmondjam neked / Szerelmem rejtett csillagrendszerét;", "szerzo": "Radnóti Miklós", "mu": "Tétova óda"},
    {"idezet": "Bájoló: / Rebbenő szemmel / Ülök a fényben, / Rózsafa rezdül / Kertünk aljában,", "szerzo": "Radnóti Miklós", "mu": "Bájoló"},
    {"idezet": "Egy mondat a zsarnokságról: / Hol zsarnokság van, / Ott zsarnokság van, / Nemcsak a puskacsőben,", "szerzo": "Illyés Gyula", "mu": "Egy mondat a zsarnokságról"},
    {"idezet": "Bartók: / Mert nemcsak az a zene, ami a húrokon zeng, / Hanem az is, ami a nép szívében él.", "szerzo": "Illyés Gyula", "mu": "Bartók"},
    {"idezet": "Apokrif: / Mert elhagyatnak akkor mindenek. / Külön egek és külön földek / Lesznek akkor.", "szerzo": "Pilinszky János", "mu": "Apokrif"},
    {"idezet": "Harbach 1944: / Minduntalan e képet látom én: / A holdfényben egy csapat ember", "szerzo": "Pilinszky János", "mu": "Harbach 1944"},
    {"idezet": "Négysoros: / Alvó szegek a jéghideg homokban. / Plakátmagányban ázó éjszakák.", "szerzo": "Pilinszky János", "mu": "Négysoros"},
    {"idezet": "Mire megjössz: / Mire megjössz, elalszik a tűz, / Csak a hamu izzik még a kandallóban.", "szerzo": "Pilinszky János", "mu": "Mire megjössz"},
