    {"idezet": "Galagonya: / Őszi éjjel / Izzik a galagonya / Izzik a galagonya / Ruhája.", "szerzo": "Weöres Sándor", "mu": "Galagonya"},
    {"idezet": "A teljesség felé: / Egyetlen igazi cél van: / Megszabadulni önmagunktól.", "szerzo": "Weöres Sándor", "mu": "A teljesség felé"},
    {"idezet": "A fiú meg a szarvasok: / Szarvasokká változtak a fiúk, / Nem mennek többé be az ajtón,", "szerzo": "Juhász Ferenc", "mu": "A tékozló ország"},
    {"idezet": "Tűz tánc: / Ég a tűz, lobog a láng, / Táncolunk körülötte mindahányan.", "szerzo": "Nagy László", "mu": "Ki viszi át a Szerelmet"},
